fn recognize(cell: [16]u8) u8 {
    const patterns = [_][4][]const u8{
        .{ " _ ", "| |", "|_|", "   " },
        .{ "   ", "  |", "  |", "   " },
        .{ " _ ", " _|", "|_ ", "   " },
        .{ " _ ", " _|", " _|", "   " },
