        .{ " _ ", "|_ ", " _|", "   " },
        .{ " _ ", "|_ ", "|_|", "   " },
        .{ " _ ", "  |", "  |", "   " },
        .{ " _ ", "|_|", "|_|", "   " },
        .{ " _ ", "|_|", " _|", "   " },
    };
    for (patterns, 0..) |rows, d| {
        var ok: bool = true;
        for (rows, 0..) |row, r| {
            if (!std.mem.eql(u8, cell[r * 3 ..][0..3], row)) {
                ok = false;
